/* stylelint-disable declaration-no-important -- legacy sheet: a stack of overrides and Caspio/inline-style fights; the flags come out together when the page is untangled (2026-09-07) */

/*
 * invoice.css — Clean, single-page invoice view.
 *
 * Design goals:
 *   - Fits on one US-Letter sheet (8.5" x 11") with ~0.4" margins
 *   - Print-first: looks identical on paper as on screen
 *   - Auto-updates from ShopWorks (no print-time recalculation)
 *   - Pacific NW palette: forest-green accent, slate ink, warm parchment background
 *
 * Loaded by /pages/invoice.html. Bumped via ?v=YYYY.MM.DD.invoice-vN.
 */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --invoice-orange: #7c2d12;
    --invoice-yellow-2: #ca8a04;
  --inv-ink:        var(--gray-800);      /* primary text */
  --inv-ink-soft:   var(--gray-600);      /* secondary text */
  --inv-ink-mute:   var(--gray-500);      /* labels, hints */
  --inv-line:       var(--gray-300);      /* borders */
  --inv-line-soft:  var(--gray-200);
  --inv-bg:         var(--color-surface);      /* paper */
  --inv-bg-zebra:   var(--gray-50);      /* table row alt */
  --inv-bg-strip:   var(--gray-100);      /* meta strip background */
  --inv-accent:     var(--print-green-dark);      /* deep forest green (NWCA primary) */
  --inv-accent-soft:var(--store-green-100);
  --inv-warn:       var(--amber-700);
  --inv-warn-soft:  var(--amber-100);
  --inv-danger:     var(--red-700);
  --inv-success:    var(--print-green);
  --inv-shadow:     0 1px 3px rgb(0 0 0 / 8%);
  --inv-radius:     4px;
}
/* stylelint-enable color-no-hex */

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 0;
  font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  line-height: 1.4;
  color: var(--inv-ink);
  background: var(--gray-200);        /* outside the "paper" */
  -webkit-font-smoothing: antialiased;
}

/* The page wrapper centers a paper-sized card on screen */
.invoice-page {
  max-width: 8.5in;
  margin: 0 auto;
  padding: 16px 16px 32px;
}

/* === Loading / Error ===================================== */

.invoice-loading,
.invoice-error {
  background: var(--inv-bg);
  border: 1px solid var(--inv-line);
  border-radius: var(--inv-radius);
  padding: 48px 32px;
  text-align: center;
  margin-top: 32px;
}

.invoice-error h2 {
  color: var(--inv-danger);
  margin: 0 0 12px;
  font-size: 20px;
}
.invoice-error p { margin: 8px 0; color: var(--inv-ink-soft); }
.invoice-error .error-help { font-size: 12px; color: var(--inv-ink-mute); }
.invoice-error a { color: var(--inv-accent); text-decoration: none; }
.invoice-error a:hover { text-decoration: underline; }

/* === Toolbar (screen only) =============================== */

.invoice-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--inv-bg);
  border: 1px solid var(--inv-line);
  border-radius: var(--inv-radius);
  margin-bottom: 12px;
  box-shadow: var(--inv-shadow);
  flex-wrap: wrap;
}

.toolbar-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  font: 500 13px Inter, sans-serif;
  color: var(--inv-ink);
  background: var(--inv-bg);
  border: 1px solid var(--inv-line);
  border-radius: var(--inv-radius);
  cursor: pointer;
  text-decoration: none;
  transition: background 0.12s, border-color 0.12s;
}

.toolbar-btn:hover {
  background: var(--inv-bg-strip);
  border-color: var(--inv-ink-mute);
}
.toolbar-btn:active { background: var(--inv-line-soft); }
.toolbar-btn:disabled { opacity: 0.6; cursor: wait; }

.toolbar-btn--primary {
  background: var(--inv-accent);
  color: var(--color-on-brand);
  border-color: var(--inv-accent);
}

.toolbar-btn--primary:hover {
  background: var(--brand-800);
  border-color: var(--brand-800);
}

.toolbar-btn--ghost {
  border-color: transparent;
  color: var(--inv-ink-soft);
}

.toolbar-btn--ghost:hover {
  background: var(--inv-bg-strip);
  border-color: var(--inv-line);
}

.toolbar-sync-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--inv-ink-mute);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.toolbar-print-tip {
  font-size: 11px;
  color: var(--inv-ink-mute);
  cursor: help;
  padding: 2px 8px;
  border-radius: 3px;
  background: var(--inv-warn-soft);
  border: 1px solid var(--amber-200);
}

.toolbar-print-tip:hover {
  background: var(--amber-200);
}

.toolbar-sync-status .pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.toolbar-sync-status .pill--ok      { background: var(--inv-accent-soft); color: var(--inv-success); }
.toolbar-sync-status .pill--pending { background: var(--gray-100);               color: var(--inv-ink-mute); }
.toolbar-sync-status .pill--stale   { background: var(--inv-warn-soft);  color: var(--inv-warn); }

/* === Invoice "paper" ===================================== */

.invoice {
  background: var(--inv-bg);
  border: 1px solid var(--inv-line);
  border-radius: var(--inv-radius);
  padding: 28px 36px 24px;
  box-shadow: var(--inv-shadow);

  /* Page-like proportions, but flexible — don't force exact 11in height */
  min-height: 9.5in;
}

/* === Header ============================================== */

.invoice-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 2px solid var(--inv-accent);
}

.invoice-header-left {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.invoice-logo {
  width: 130px;
  height: auto;
  object-fit: contain;
  flex-shrink: 0;
}

.invoice-company-meta {
  font-size: 11px;
  line-height: 1.45;
  color: var(--inv-ink-soft);
}

.invoice-company-name {
  font-weight: 700;
  font-size: 13px;
  color: var(--inv-ink);
  margin-bottom: 2px;
}
.invoice-company-line { color: var(--inv-ink-mute); }

.invoice-header-right {
  text-align: right;
  min-width: 220px;
}

.invoice-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--inv-accent);
  margin-bottom: 8px;
}

.invoice-meta-row {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  font-size: 12px;
  line-height: 1.6;
}

.invoice-meta-label {
  color: var(--inv-ink-mute);
  font-weight: 500;
  min-width: 60px;
  text-align: right;
}

.invoice-meta-value {
  color: var(--inv-ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.invoice-rush-badge {
  display: inline-block;
  background: var(--inv-danger);
  color: var(--color-on-brand);
  padding: 3px 10px;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* === Status banner (RUSH, expedite, etc.) ================ */

.invoice-status-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--red-100);
  border: 1px solid var(--red-200);
  border-left: 4px solid var(--inv-danger);
  border-radius: 3px;
  margin-bottom: 14px;
  font-size: 12px;
  color: var(--red-800);
}

.invoice-status-icon {
  font-size: 16px;
  line-height: 1;
}

.invoice-status-text {
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--inv-danger);
}

.invoice-status-detail {
  color: var(--invoice-orange);
  font-weight: 500;
}

/* Cancelled variant — visually distinct from RUSH (darker red,
   no left-border accent, strikes a "voided" tone). */
.invoice-status-banner--cancelled {
  background: var(--red-50);
  border: 2px solid var(--red-700);
  border-left: 2px solid var(--red-700);
  color: var(--print-red);
}

.invoice-status-banner--cancelled .invoice-status-text {
  color: var(--print-red);
}

.invoice-status-banner--cancelled .invoice-status-detail {
  color: var(--red-800);
}

/* === Bill To + Ship To =================================== */

.invoice-addresses {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 18px;
}

.invoice-address-block {
  border: 1px solid var(--inv-line-soft);
  border-radius: var(--inv-radius);
  padding: 10px 12px;
  background: var(--inv-bg-zebra);
}

.invoice-address-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--inv-ink-mute);
  font-weight: 600;
  margin-bottom: 4px;
}

.invoice-address-name {
  font-weight: 700;
  font-size: 13px;
  color: var(--inv-ink);
  margin-bottom: 2px;
}

.invoice-address-line {
  font-size: 12px;
  color: var(--inv-ink-soft);
  line-height: 1.45;
}

.invoice-ship-method {
  margin-top: 4px;
  font-weight: 600;
  color: var(--inv-accent);
}

/* === Order details strip ================================= */

.invoice-details {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  background: var(--inv-bg-strip);
  border-radius: var(--inv-radius);
  padding: 10px 12px;
  margin-bottom: 16px;
}

.invoice-detail-cell {
  display: flex;
  flex-direction: column;
}

.invoice-detail-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--inv-ink-mute);
  font-weight: 600;
  margin-bottom: 2px;
}

.invoice-detail-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--inv-ink);
}

.invoice-detail-cell--method .invoice-detail-value {
  color: var(--inv-accent);
}

/* === Line items table ==================================== */

.invoice-items {
  margin-bottom: 20px;
}

.invoice-items-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.invoice-items-table thead th {
  text-align: left;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--inv-ink-mute);
  font-weight: 600;
  border-bottom: 1.5px solid var(--inv-ink-soft);
  padding: 8px 6px;
  background: var(--inv-bg);
}

.invoice-items-table tbody td {
  padding: 7px 6px;
  border-bottom: 1px solid var(--inv-line-soft);
  vertical-align: top;
  color: var(--inv-ink);
}

.invoice-items-table tbody tr:nth-child(even) td {
  background: var(--inv-bg-zebra);
}
.invoice-items-table .col-style    { width: 14%; font-weight: 600; }
.invoice-items-table .col-color    { width: 16%; }
.invoice-items-table .col-desc     { width: 36%; color: var(--inv-ink-soft); }
.invoice-items-table .col-qty      { width: 8%;  text-align: right; font-variant-numeric: tabular-nums; }
.invoice-items-table .col-unit     { width: 12%; text-align: right; font-variant-numeric: tabular-nums; }
.invoice-items-table .col-total    { width: 14%; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }

.invoice-item-sub {
  font-size: 10.5px;
  color: var(--inv-ink-mute);
  margin-top: 2px;
}

.invoice-item-locations {
  display: inline-block;
  margin-top: 3px;
  padding: 1px 7px;
  background: var(--inv-accent-soft);
  color: var(--inv-success);
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
}

.invoice-item-empty td {
  text-align: center;
  padding: 24px;
  color: var(--inv-ink-mute);
  font-style: italic;
}

/* Audit fix H3: grouped line items (base SKU parent + per-size children) */
.invoice-item-row--group-parent td {
  font-weight: 600;
  border-top: 1px solid var(--inv-line);
}

.invoice-item-row--group-parent .col-style {
  color: var(--inv-ink);
}

.invoice-item-row--group-child td {
  background: var(--inv-bg-zebra);
  color: var(--inv-ink-soft);
  font-size: 11.5px;
  border-bottom: 1px solid var(--inv-line-soft);
}

.invoice-item-row--group-child .col-style {
  padding-left: 18px;        /* indent the child SKU under the parent */
  color: var(--inv-ink-mute);
  font-weight: 400;
}

.invoice-item-row--group-child .col-desc {
  color: var(--inv-ink-mute);
}

.invoice-section-row td {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--inv-ink-mute);
  background: var(--inv-bg-strip) !important;
  font-weight: 700;
  padding: 5px 6px;
  border-bottom: 1px solid var(--inv-line);
}

/* === Totals ============================================== */

.invoice-totals {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 16px;
}

.invoice-totals-inner {
  width: 280px;
  font-size: 12px;
}

.invoice-totals-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  color: var(--inv-ink-soft);
}
.invoice-totals-label { color: var(--inv-ink-soft); }

.invoice-totals-value {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  color: var(--inv-ink);
}

.invoice-totals-rate {
  display: inline;
  margin-left: 4px;
  color: var(--inv-ink-mute);
  font-size: 11px;
  font-weight: 500;
}

.invoice-totals-row--grand {
  border-top: 2px solid var(--inv-ink);
  margin-top: 6px;
  padding-top: 8px;
  font-size: 14px;
}

.invoice-totals-row--grand .invoice-totals-label,
.invoice-totals-row--grand .invoice-totals-value {
  color: var(--inv-ink);
  font-weight: 700;
}

.invoice-totals-row--balance {
  border-top: 1px dashed var(--inv-line);
  margin-top: 4px;
  padding-top: 6px;
}

.invoice-totals-row--balance .invoice-totals-label,
.invoice-totals-row--balance .invoice-totals-value {
  color: var(--inv-warn);
  font-weight: 700;
}

/* AMOUNT DUE — the "payment ask" row. QuickBooks-style: double border
   top, accent color, biggest font in the totals stack. */
.invoice-totals-row--amount-due {
  border-top: 3px double var(--inv-accent);
  margin-top: 6px;
  padding-top: 9px;
}

.invoice-totals-row--amount-due .invoice-totals-label,
.invoice-totals-row--amount-due .invoice-totals-value {
  color: var(--inv-accent);
  font-weight: 800;
  font-size: 17px;
  letter-spacing: 0.02em;
}

/* === Payment info block ================================== */

.invoice-payment-info {
  margin-bottom: 14px;
}

.invoice-payment-block {
  background: var(--store-paper);
  border: 1px solid var(--amber-200);
  border-left: 4px solid var(--invoice-yellow-2);
  border-radius: 3px;
  padding: 10px 14px;
}

.invoice-payment-heading {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--amber-800);
  font-weight: 700;
  margin-bottom: 4px;
}

.invoice-payment-body {
  font-size: 11px;
  color: var(--amber-900);
  line-height: 1.5;
}

.invoice-payment-body a {
  color: var(--inv-accent);
  font-weight: 600;
  text-decoration: none;
}
.invoice-payment-body a:hover { text-decoration: underline; }

/* === Customer Artwork & Mockups ==========================
 * (2026-06-10) Custom T-Shirts storefront orders only — original
 * uploaded art + approved mockups from OrderSettingsJSON. Mounted
 * by invoice.js renderCustomerArtwork() between the line items and
 * the totals. Screen-only: hidden in @media print so the printed /
 * PDF invoice stays a clean one-pager.
 */

.cust-art-section {
  margin: 14px 0;
  padding: 12px;
  background: var(--inv-bg-zebra);
  border: 1px solid var(--inv-line-soft);
  border-radius: var(--inv-radius);
}

.cust-art-heading {
  font-size: 12px;
  font-weight: 700;
  color: var(--inv-accent);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.cust-art-subhead {
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--inv-ink-mute);
  margin: 10px 0 8px;
}

.cust-art-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
}

.cust-art-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
  background: var(--inv-bg);
  border: 1px solid var(--inv-line-soft);
  border-radius: var(--inv-radius);
}

.cust-art-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: var(--inv-radius);
  overflow: hidden;
  background: var(--inv-bg);
  border: 1px solid var(--inv-line-soft);
  text-decoration: none;
  color: inherit;
}
.cust-art-thumb:hover { border-color: var(--inv-accent); }

.cust-art-thumb img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.cust-art-thumb-icon {
  font-size: 32px;
  color: var(--inv-ink-mute);
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  display: flex;
}
.cust-art-meta { text-align: center; }

.cust-art-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--inv-ink);
  margin-bottom: 2px;
}

.cust-art-filename {
  font-size: 10px;
  color: var(--inv-ink-mute);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.cust-art-download {
  display: inline-block;
  margin-top: 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--inv-accent);
  text-decoration: none;
}
.cust-art-download:hover { text-decoration: underline; }

/* === Footer ============================================== */

.invoice-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding-top: 12px;
  margin-top: 16px;
  border-top: 1px solid var(--inv-line-soft);
  font-size: 10.5px;
  color: var(--inv-ink-mute);
}
.invoice-footer a { color: var(--inv-accent); text-decoration: none; }
.invoice-footer a:hover { text-decoration: underline; }

.invoice-footer-right {
  text-align: right;
  font-style: italic;
}

/* === Print ===============================================
 * Goal: Single 8.5x11" letter page, looks like a real invoice
 * (QuickBooks-style). Print rules must EXPLICITLY restore the
 * desktop 2-column layout — otherwise the @media (max-width:700)
 * mobile rules below cascade through when printing from a narrow
 * browser viewport.
 */

@media print {
  /* 0.25in margin gives Chrome/Edge headers + footers less room to display
     date/URL/page-number, while still respecting the printer's hardware
     non-printable region. For zero-artifact PDFs the user should also uncheck
     "Headers and footers" in the print dialog (one-time setting). */
  @page {
    size: letter;
    margin: 0.25in;
  }

  /* Force all colors/backgrounds to render in print (critical for
     header rule, address backgrounds, tax-rate pill, location chip
     and the green accents). */
  html, body, *, *::before, *::after {
    -webkit-print-color-adjust: exact !important;
    color-adjust: exact !important;
  }

  html, body {
    background: var(--color-surface) !important;
    margin: 0 !important;
    padding: 0 !important;
    font-size: 10pt;
    line-height: 1.35;
    color: var(--gray-800) !important;
  }

  .invoice-page {
    max-width: none !important;
    padding: 0 !important;
    margin: 0 !important;
  }

  /* Hide all on-screen chrome */
  .invoice-toolbar,
  .invoice-loading,
  .invoice-error,
  .toolbar-sync-status {
    display: none !important;
  }

  /* Customer artwork strip is a staff/screen aid — keep the printed
     invoice a clean one-pager. */
  .cust-art-section {
    display: none !important;
  }

  .invoice {
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    min-height: auto !important;
    background: var(--color-surface) !important;
  }

  /* Header — explicit 2-column even if printing from mobile */
  .invoice-header {
    display: flex !important;
    flex-direction: row !important;
    align-items: flex-start !important;
    justify-content: space-between !important;
    gap: 20px !important;
    padding-bottom: 10px !important;
    margin-bottom: 12px !important;
    border-bottom: 2.5px solid var(--print-green-dark) !important;
  }

  .invoice-header-left {
    display: flex !important;
    gap: 12px !important;
    align-items: flex-start !important;
  }
  .invoice-logo { width: 100px !important; height: auto !important; }
  .invoice-company-meta { font-size: 8.5pt !important; line-height: 1.4 !important; }
  .invoice-company-name { font-size: 9.5pt !important; }

  .invoice-header-right {
    text-align: right !important;
    min-width: 200px !important;
  }

  .invoice-title {
    font-size: 22pt !important;
    color: var(--print-green-dark) !important;
    margin-bottom: 6px !important;
    letter-spacing: 0.04em !important;
  }

  .invoice-meta-row {
    display: flex !important;
    justify-content: flex-end !important;
    gap: 10px !important;
    font-size: 9pt !important;
  }
  .invoice-meta-label { text-align: right !important; min-width: 52px !important; }

  /* Bill To + Ship To — explicit 2-column */
  .invoice-addresses {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 14px !important;
    margin-bottom: 10px !important;
  }

  .invoice-address-block {
    background: var(--gray-50) !important;
    border: 1px solid var(--gray-300) !important;
    padding: 8px 10px !important;
    border-radius: 3px !important;
  }

  .invoice-address-label {
    font-size: 7.5pt !important;
    letter-spacing: 0.1em !important;
    color: var(--gray-500) !important;
  }
  .invoice-address-name { font-size: 10pt !important; }
  .invoice-address-line { font-size: 9pt !important; }
  .invoice-ship-method { color: var(--print-green-dark) !important; font-weight: 600 !important; }

  /* Details strip — 5 columns horizontal */
  .invoice-details {
    display: grid !important;
    grid-template-columns: repeat(5, 1fr) !important;
    gap: 8px !important;
    background: var(--gray-100) !important;
    padding: 7px 9px !important;
    margin-bottom: 10px !important;
    border-radius: 3px !important;
  }

  .invoice-detail-label {
    font-size: 7.5pt !important;
    letter-spacing: 0.08em !important;
    color: var(--gray-500) !important;
  }
  .invoice-detail-value { font-size: 9pt !important; }

  .invoice-detail-cell--method .invoice-detail-value {
    color: var(--print-green-dark) !important;
  }

  /* Line items table */
  .invoice-items {
    margin-bottom: 12px !important;
  }

  .invoice-items-table thead {
    display: table-header-group !important;  /* repeat header on page 2 if needed */
  }

  .invoice-items-table thead th {
    padding: 5px 4px !important;
    font-size: 8pt !important;
    color: var(--gray-600) !important;
    background: var(--gray-100) !important;
    border-bottom: 1.5px solid var(--gray-700) !important;
  }

  .invoice-items-table tbody td {
    padding: 4px !important;
    font-size: 9pt !important;
    border-bottom: 1px solid var(--gray-200) !important;
  }

  .invoice-items-table tbody tr {
    break-inside: avoid;
  }

  /* Disable zebra in print (looks cleaner on paper) */
  .invoice-items-table tbody tr:nth-child(even) td {
    background: var(--color-surface) !important;
  }
  .invoice-items-table .col-style    { width: 14% !important; }
  .invoice-items-table .col-color    { width: 13% !important; }
  .invoice-items-table .col-desc     { width: 39% !important; }
  .invoice-items-table .col-qty      { width: 7%  !important; }
  .invoice-items-table .col-unit     { width: 12% !important; }
  .invoice-items-table .col-total    { width: 15% !important; }

  .invoice-item-locations {
    background: var(--store-green-100) !important;
    color: var(--print-green) !important;
    border: 1px solid var(--green-200) !important;
    font-size: 7.5pt !important;
  }

  /* Totals — keep together on one page */
  .invoice-totals {
    break-inside: avoid;
    margin-bottom: 12px !important;
  }
  .invoice-totals-inner { width: 260px !important; font-size: 9.5pt !important; }
  .invoice-totals-row { padding: 3px 0 !important; }

  .invoice-totals-rate {
    background: var(--gray-100) !important;
    color: var(--gray-500) !important;
    font-size: 7.5pt !important;
  }

  .invoice-totals-row--grand {
    border-top: 2px solid var(--gray-800) !important;
    margin-top: 4px !important;
    padding-top: 6px !important;
    font-size: 12pt !important;
  }

  .invoice-totals-row--grand .invoice-totals-label,
  .invoice-totals-row--grand .invoice-totals-value {
    color: var(--gray-800) !important;
    font-weight: 700 !important;
  }

  .invoice-totals-row--balance {
    border-top: 1px dashed var(--gray-300) !important;
    margin-top: 3px !important;
    padding-top: 5px !important;
  }

  .invoice-totals-row--balance .invoice-totals-label,
  .invoice-totals-row--balance .invoice-totals-value {
    color: var(--amber-700) !important;
    font-weight: 700 !important;
  }

  /* AMOUNT DUE — biggest, accent-colored line in the totals stack */
  .invoice-totals-row--amount-due {
    border-top: 3px double var(--print-green-dark) !important;
    margin-top: 5px !important;
    padding-top: 8px !important;
  }

  .invoice-totals-row--amount-due .invoice-totals-label,
  .invoice-totals-row--amount-due .invoice-totals-value {
    color: var(--print-green-dark) !important;
    font-weight: 800 !important;
    font-size: 14pt !important;
  }

  /* Status banner (RUSH) — full-width, attention-grabbing */
  .invoice-status-banner {
    display: flex !important;
    background: var(--red-100) !important;
    border: 1px solid var(--red-200) !important;
    border-left: 4px solid var(--red-700) !important;
    color: var(--red-800) !important;
    padding: 8px 12px !important;
    margin-bottom: 12px !important;
    font-size: 9.5pt !important;
  }
  .invoice-status-text { color: var(--red-700) !important; }
  .invoice-status-detail { color: var(--invoice-orange) !important; }

  /* Cancelled variant for print — heavier border, voided look */
  .invoice-status-banner--cancelled {
    background: var(--red-50) !important;
    border: 2px solid var(--red-700) !important;
    color: var(--print-red) !important;
  }
  .invoice-status-banner--cancelled .invoice-status-text { color: var(--print-red) !important; }
  .invoice-status-banner--cancelled .invoice-status-detail { color: var(--red-800) !important; }

  /* Payment instructions block — keep with totals on same page */
  .invoice-payment-info {
    break-inside: avoid;
    margin-bottom: 10px !important;
  }

  .invoice-payment-block {
    background: var(--store-paper) !important;
    border: 1px solid var(--amber-200) !important;
    border-left: 4px solid var(--invoice-yellow-2) !important;
    padding: 8px 12px !important;
  }

  .invoice-payment-heading {
    color: var(--amber-800) !important;
    font-size: 7.5pt !important;
  }

  .invoice-payment-body {
    color: var(--amber-900) !important;
    font-size: 8.5pt !important;
    line-height: 1.45 !important;
  }
  .invoice-payment-body a { color: var(--print-green-dark) !important; }

  /* Hide the toolbar print tip — it's screen-only */
  .toolbar-print-tip { display: none !important; }

  /* Footer */
  .invoice-footer {
    break-inside: avoid;
    border-top: 1px solid var(--gray-300) !important;
    padding-top: 8px !important;
    margin-top: 10px !important;
    font-size: 8pt !important;
    color: var(--gray-500) !important;
  }
  .invoice-footer a { color: var(--print-green-dark) !important; }
}

/* === Small-screen graceful degradation =================== */

@media (width <= 700px) {
  .invoice {
    padding: 16px 18px;
    min-height: auto;
  }

  .invoice-header {
    flex-direction: column;
    gap: 12px;
  }
  .invoice-header-right { text-align: left; min-width: 0; }
  .invoice-meta-row { justify-content: flex-start; }
  .invoice-meta-label { text-align: left; }
  .invoice-addresses { grid-template-columns: 1fr; }

  .invoice-details {
    grid-template-columns: repeat(2, 1fr);
  }
  .invoice-items-table { font-size: 11px; }
  .invoice-items-table .col-desc { width: auto; }
  .invoice-totals-inner { width: 100%; }
}

