retiredStyles.css:
/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --customer-invoice-gray: #888;
    --customer-invoice-gray-2: #666;
 --nw-dark:var(--brand-800); --nw-med:var(--brand-mid); }
/* stylelint-enable color-no-hex */
* { box-sizing: border-box; }

body { margin:0; background:var(--store-paper-deep); color:var(--print-ink); padding:0 0 30px;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif; }

.ci-toolbar { display:flex; justify-content:space-between; align-items:center; max-width:800px; margin:0 auto; padding:14px 18px; }
.ci-back { color:var(--nw-med); text-decoration:none; font-size:14px; }
.ci-btn { background:var(--nw-med); color:var(--color-surface); border:none; border-radius:8px; padding:9px 18px; font-size:14px; font-weight:600; cursor:pointer; box-shadow:0 3px 10px rgb(58 124 82 / 25%); }
.ci-btn:hover { background:var(--nw-dark); }
.ci-btn:disabled { opacity:.6; cursor:default; }
.ci-status { max-width:800px; margin:40px auto; text-align:center; color:var(--customer-invoice-gray); }
.ci-status a { color:var(--nw-med); }

.ci-paper { max-width:800px; margin:0 auto; background:var(--color-surface); padding:26px 30px; box-shadow:0 2px 16px rgb(0 0 0 / 8%); }
.ci-head { display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2.5px solid var(--nw-dark); padding-bottom:10px; }
.ci-head-left { max-width:56%; }
.ci-logo { max-width:175px; height:auto; }
.ci-from { font-size:10.5px; color:var(--print-ink-soft); line-height:1.45; margin-top:5px; }
.ci-head-right { text-align:right; }
.ci-inv-title { font-size:19px; font-weight:700; color:var(--nw-dark); margin:0 0 3px; }
.ci-inv-meta { font-size:11px; color:var(--print-ink-soft); line-height:1.5; }

.ci-parties { margin:12px 0 4px; font-size:12px; }
.ci-party h3 { font-size:10px; text-transform:uppercase; letter-spacing:.5px; color:var(--print-line); margin:0 0 3px; }
.ci-party p { margin:1px 0; }

.ci-meta-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:6px 12px; margin:10px 0 4px; padding:9px 12px; background:var(--gray-100); border-radius:7px; font-size:11.5px; }
.ci-meta-grid .k { color:var(--print-line); text-transform:uppercase; font-size:9.5px; letter-spacing:.5px; }
.ci-meta-grid .v { color:var(--print-ink); font-weight:600; }

.ci-table { width:100%; border-collapse:collapse; margin-top:10px; font-size:11.5px; }
.ci-table th { background:var(--nw-dark); color:var(--color-surface); text-align:left; padding:6px 9px; font-weight:600; }
.ci-table th.num, .ci-table td.num { text-align:right; }
.ci-table td { padding:5px 9px; border-bottom:1px solid var(--brand-100); vertical-align:top; }
.ci-item-part { font-weight:600; }
.ci-item-sizes { color:var(--customer-invoice-gray); font-size:10.5px; margin-top:1px; }

.ci-totals { margin-top:12px; display:flex; justify-content:flex-end; }
.ci-totals table { font-size:12px; min-width:240px; }
.ci-totals td { padding:3px 8px; }
.ci-totals td.lbl { color:var(--customer-invoice-gray-2); text-align:right; }
.ci-totals td.amt { text-align:right; font-variant-numeric:tabular-nums; min-width:90px; }
.ci-totals tr.grand td { font-weight:700; font-size:14px; color:var(--nw-dark); border-top:2px solid var(--nw-dark); }
.ci-totals tr.bal td { font-weight:700; color:var(--color-ae); }
.ci-totals tr.bal.paid td { color:var(--nw-dark); }

.ci-foot { margin-top:16px; text-align:center; color:var(--gray-400); font-size:10.5px; border-top:1px solid var(--brand-100); padding-top:9px; }

@media print { body { background:var(--color-surface); } .ci-toolbar { display:none; } .ci-paper { box-shadow:none; margin:0; max-width:100%; padding:0; } }

@media (width <=640px) { .ci-paper { padding:20px 16px; } .ci-meta-grid { grid-template-columns:repeat(2,1fr); } }

/* 2026-09-05 review: the hidden attribute must beat any display rule */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

/* 2026-09-06 review */
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
